def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = sum(1 for a in op if a == 'C')
    op_d = n - op_c
    my_c = sum(1 for a in my if a == 'C')
    my_d = n - my_c

    op_last = op[-1]
    my_last = my[-1]

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            opp_c_streak += 1
        else:
            break

    r10 = min(10, n)
    r20 = min(20, n)
    recent_c10 = sum(1 for a in op[-r10:] if a == 'C')
    recent_c20 = sum(1 for a in op[-r20:] if a == 'C')

    # A clear sign that a defection was not punished:
    # we defected while opponent cooperated, then both cooperated next round.
    confirmed_exploitable = False
    start = max(0, n - 12)
    for i in range(start, n - 1):
        if (my[i] == 'D' and op[i] == 'C' and
                my[i + 1] == 'C' and op[i + 1] == 'C'):
            confirmed_exploitable = True
            break

    # Strong persistence of opponent defection: stop forgiving.
    if n >= 12 and recent_c10 == 0 and opp_d_streak >= 8:
        return 'D'

    # Opponent has never defected.  Once a probe shows no punishment, exploit.
    if op_d == 0:
        if confirmed_exploitable:
            return 'D'
        if my_d > 0:
            # Just after a probe, cooperate once to see whether punishment appears.
            return 'C'
        if n >= 60:
            return 'D'
        return 'C'

    # Opponent defected last round.
    if op_last == 'D':
        if opp_d_streak == 1:
            # Forgiving isolated defections helps against TFT-like opponents.
            if op_c >= 3 and (op_c >= 2 * op_d or recent_c10 >= 3):
                return 'C'
            return 'D'

        if opp_d_streak <= 3:
            return 'D'

        # Long D streak: try one limited reset if they have cooperated recently.
        if my_last == 'C':
            # We already tried to break the loop. If two C,D attempts failed, punish.
            if n >= 2 and my[-2] == 'C' and op[-2] == 'D':
                return 'D'
            return 'C'

        if n >= 2 and my[-2] == 'C' and op[-2] == 'D':
            return 'D'

        if opp_d_streak >= 5 and recent_c10 > 2:
            return 'C'

        return 'D'

    # Opponent cooperated last round.
    if my_last == 'D':
        if confirmed_exploitable:
            return 'D'
        # Otherwise, cooperate once to observe whether the previous D was punished.
        return 'C'

    # Stable mutual cooperation.
    if confirmed_exploitable and recent_c10 >= 5 and op_c > op_d:
        return 'D'

    # Controlled late-stage tests against very cooperative opponents, especially
    # all-C after a small known defect count.
    if n >= 30 and r20 >= 12 and recent_c20 == r20:
        if op_d == 4 or (op_d <= 4 and n >= 70):
            return 'D'

    return 'C'
